@router.delete("/customers/{customer_id}/purge", status_code=202)
def schedule_customer_purge(
    customer_id: str,
    background_tasks: BackgroundTasks,
    user: User = Depends(get_current_user)
):
    if customer_id != user.customer_id:
        raise HTTPException(status_code=403, detail="Not authorized to purge another customer's records")

    background_tasks.add_task(purge_customer_records_task, customer_id)
    return {"status": "accepted", "message": "Purge job scheduled"}
